"""
Focused demonstration: the archimedean tower is what the local topology sees.

This script builds a census of a fixed sample of surreal-like numbers and shows how
they are grouped into archimedean monads as the scale d descends the tower
d = 1, eps, eps^2, ....  It then verifies, on that sample, the three structural facts
that make monads the right local invariant:

  (i)   monad(c, d) is contained in the interval (c - d, c + d)  -- so monads are
        genuine neighbourhoods and form a basis;
  (ii)  at a fixed scale, two monads are equal or disjoint -- the "same monad"
        relation is an equivalence;
  (iii) refining the scale strictly refines the partition -- descending the tower
        always splits at least one class, which is why the tower, and hence any
        neighbourhood basis, cannot be exhausted by a set.

Exact rational arithmetic throughout.  Run:  python3 demo2.py
"""

from __future__ import annotations

from fractions import Fraction
from itertools import combinations
from typing import Dict, List, Optional, Sequence, Tuple

Elem = Dict[Fraction, Fraction]


def add(x: Elem, y: Elem) -> Elem:
    out = dict(x)
    for q, a in y.items():
        out[q] = out.get(q, Fraction(0)) + a
    return {q: a for q, a in out.items() if a != 0}


def sub(x: Elem, y: Elem) -> Elem:
    return add(x, {q: -a for q, a in y.items()})


def lead(x: Elem) -> Optional[Fraction]:
    nz = {q: a for q, a in x.items() if a != 0}
    return min(nz) if nz else None


def sign(x: Elem) -> int:
    q = lead(x)
    return 0 if q is None else (1 if x[q] > 0 else -1)


def less(x: Elem, y: Elem) -> bool:
    return sign(sub(x, y)) < 0


def show(x: Elem) -> str:
    if not x:
        return "0"
    parts: List[str] = []
    for q in sorted(x):
        a = x[q]
        if q == 0:
            parts.append(f"{a}")
        elif q == 1:
            parts.append(f"{a}eps")
        else:
            parts.append(f"{a}eps^{q}")
    return " + ".join(parts).replace("+ -", "- ")


def in_monad(z: Elem, c: Elem, d: Elem) -> bool:
    qd = lead(d)
    if qd is None:
        raise ValueError("scale must be nonzero")
    qz = lead(sub(z, c))
    return qz is None or qz > qd


def partition(points: Sequence[Elem], d: Elem) -> List[List[int]]:
    reps: List[Elem] = []
    groups: List[List[int]] = []
    for i, z in enumerate(points):
        for j, rep in enumerate(reps):
            if in_monad(z, rep, d):
                groups[j].append(i)
                break
        else:
            reps.append(z)
            groups.append([i])
    return groups


def main() -> None:
    sample: List[Elem] = [
        {},                                                     # 0
        {Fraction(3): Fraction(1)},                             # eps^3
        {Fraction(2): Fraction(-4)},                            # -4 eps^2
        {Fraction(1): Fraction(1)},                             # eps
        {Fraction(1): Fraction(1000000)},                       # 10^6 eps
        {Fraction(0): Fraction(1, 1000)},                       # 1/1000
        {Fraction(0): Fraction(1)},                             # 1
        {Fraction(0): Fraction(1), Fraction(2): Fraction(1)},   # 1 + eps^2
        {Fraction(0): Fraction(1), Fraction(1): Fraction(-7)},  # 1 - 7 eps
        {Fraction(-1): Fraction(1)},                            # omega-sized
    ]

    print("Sample points:")
    for i, z in enumerate(sample):
        print(f"  [{i}] {show(z)}")
    print()

    scales: List[Elem] = [
        {Fraction(0): Fraction(1)},
        {Fraction(1): Fraction(1)},
        {Fraction(2): Fraction(1)},
        {Fraction(3): Fraction(1)},
    ]

    previous: Optional[List[List[int]]] = None
    for d in scales:
        groups = partition(sample, d)
        print(f"scale d = {show(d)}:  {len(groups)} monads")
        for g in groups:
            print("     { " + ", ".join(show(sample[i]) for i in g) + " }")

        # (i) monads sit inside (c - d, c + d)
        for g in groups:
            c = sample[g[0]]
            for i in g:
                z = sample[i]
                assert less(sub(c, d), z) and less(z, add(c, d)), "monad escapes its interval"

        # (ii) equal or disjoint
        for g1, g2 in combinations(groups, 2):
            assert not (set(g1) & set(g2)), "monads at one scale overlap"

        # (iii) strict refinement of the previous partition
        if previous is not None:
            assert len(groups) >= len(previous), "refinement lost classes"
            for g in groups:
                assert any(set(g) <= set(h) for h in previous), "not a refinement"
        previous = groups
        print()

    print("Verified on this sample:")
    print("  (i)   every monad is contained in the interval (c - d, c + d);")
    print("  (ii)  monads at a fixed scale are pairwise disjoint;")
    print("  (iii) each descent of the scale refines the partition.")
    print()
    print("The tower of scales continues past every ordinal, so no set of monads")
    print("exhausts it -- which is exactly why no point has a set-sized neighbourhood basis.")


if __name__ == "__main__":
    main()

