"""Algorithm 1 — Conway Cut Witness Construction.

Given finitely many positive elements of a computable ordered field with
infinitesimals (a Levi-Civita-style model of a fragment of the surreal line),
construct a positive element strictly below all of them.  This is the executable
content of the coinitiality-failure theorem:  y = { 0 | r_1, ..., r_N }.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Dict, List, Optional, Sequence, Tuple

Term = Tuple[Fraction, Fraction]  # (exponent q, coefficient a) in a * eps^q


def leading_term(x: Dict[Fraction, Fraction]) -> Optional[Term]:
    """Term of least exponent (= greatest order of magnitude); None if x = 0."""
    nz = {q: a for q, a in x.items() if a != 0}
    if not nz:
        return None
    q = min(nz)
    return (q, nz[q])


def is_positive(x: Dict[Fraction, Fraction]) -> bool:
    lead = leading_term(x)
    return lead is not None and lead[1] > 0


def conway_cut_below(family: Sequence[Dict[Fraction, Fraction]]) -> Dict[Fraction, Fraction]:
    """Return y with 0 < y < r for every r in `family`.

    Correctness: let q* be the greatest leading exponent occurring in the family
    (that is, the order of magnitude of the *smallest* member).  Then
    y = eps^{q* + 1} is positive and has strictly greater exponent than every
    member's leading term, hence is strictly smaller than each of them.

    Complexity: O(N) comparisons of rationals, where N = len(family); the output
    has a single term, so the construction does not grow with N.  In the surreal
    setting the analogous construction is a single Conway cut and works for a
    family of arbitrary cardinality, not merely a finite one.
    """
    for r in family:
        if not is_positive(r):
            raise ValueError("every member of the family must be strictly positive")
    if not family:
        return {Fraction(0): Fraction(1)}
    q_star = max(leading_term(r)[0] for r in family)  # type: ignore[index]
    return {q_star + 1: Fraction(1)}


def relative_infinitesimal(d: Dict[Fraction, Fraction], depth: int = 32
                           ) -> Dict[Fraction, Fraction]:
    """A positive element below d * 2^{-n} for every n <= depth (and, in the
    surreal model, for every n at all): apply the cut to the dyadic ladder."""
    ladder: List[Dict[Fraction, Fraction]] = []
    for n in range(depth + 1):
        scaled = {q: a * Fraction(1, 2 ** n) for q, a in d.items()}
        ladder.append(scaled)
    return conway_cut_below(ladder)


if __name__ == "__main__":
    fam = [
        {Fraction(0): Fraction(1)},                    # 1
        {Fraction(0): Fraction(1, 10 ** 9)},           # 10^-9
        {Fraction(1): Fraction(1)},                    # eps
        {Fraction(5, 2): Fraction(7)},                 # 7 eps^{5/2}
    ]
    print("witness:", conway_cut_below(fam))
    print("relative infinitesimal below all d*2^-n for d = eps:",
          relative_infinitesimal({Fraction(1): Fraction(1)}))

"""Algorithm 4 — Supremum Refutation for Upper Monads (local-compactness obstruction).

The upper monad U(c, d) = monad(c, d) cap (c, infinity) has no least upper bound.
Given any candidate x, this procedure returns an explicit certificate of failure:
either a member of U(c, d) strictly above x (so x is not an upper bound), or a
strictly smaller upper bound (so x is not the least one).

Since U(c, d) is contained in every sufficiently small neighbourhood of c, and a
compact subset of a linearly ordered space must supply least upper bounds for its
nonempty closed subsets, this refutation shows that no neighbourhood of any point
is compact.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Dict, Optional, Tuple

Elem = Dict[Fraction, Fraction]
Certificate = Tuple[str, Elem]


def add(x: Elem, y: Elem) -> Elem:
    out = dict(x)
    for q, a in y.items():
        out[q] = out.get(q, Fraction(0)) + a
    return {q: a for q, a in out.items() if a != 0}


def sub(x: Elem, y: Elem) -> Elem:
    return add(x, {q: -a for q, a in y.items()})


def scale_by(x: Elem, c: Fraction) -> Elem:
    return {q: a * c for q, a in x.items() if a * c != 0}


def leading_exponent(x: Elem) -> Optional[Fraction]:
    nz = {q: a for q, a in x.items() if a != 0}
    return min(nz) if nz else None


def sign(x: Elem) -> int:
    nz = {q: a for q, a in x.items() if a != 0}
    if not nz:
        return 0
    return 1 if nz[min(nz)] > 0 else -1


def in_monad(z: Elem, c: Elem, d: Elem) -> bool:
    qd = leading_exponent(d)
    qz = leading_exponent(sub(z, c))
    return qz is None or (qd is not None and qz > qd)


def refute_supremum(x: Elem, c: Elem, d: Elem) -> Certificate:
    """Return a certificate that x is not the least upper bound of U(c, d).

    Case analysis (mirroring the proof):
      * If x <= c, then c + e for a relative infinitesimal e beats it.
      * If x lies in monad(c, d), then w = c + 2(x - c) is still in the monad
        (doubling an infinitesimal keeps it infinitesimal, by the identity
        d*2^{-(n+1)} + d*2^{-(n+1)} = d*2^{-n}) and w > x, so x is not an
        upper bound.
      * Otherwise x - c >= d*2^{-n} for some n, and x' = c + d*2^{-(n+1)} is a
        strictly smaller upper bound of U(c, d), so x is not least.

    Complexity: O(1) in the monad case; O(log(magnitude)) dyadic steps otherwise,
    and O(1) in the exponent model since the relevant n is read off directly.
    """
    qd = leading_exponent(d)
    if qd is None or sign(d) <= 0:
        raise ValueError("scale d must be positive")

    if sign(sub(x, c)) <= 0:
        return ("not an upper bound", add(c, {qd + 1: Fraction(1)}))

    if in_monad(x, c, d):
        return ("not an upper bound", add(c, scale_by(sub(x, c), Fraction(2))))

    # x is outside the monad: find the dyadic level it exceeds.
    n = 0
    while sign(sub(sub(x, c), scale_by(d, Fraction(1, 2 ** n)))) < 0:
        n += 1
        if n > 4096:
            raise RuntimeError("no finite dyadic level found")
    return ("not least", add(c, scale_by(d, Fraction(1, 2 ** (n + 1)))))


if __name__ == "__main__":
    c: Elem = {}
    d: Elem = {Fraction(0): Fraction(1)}
    for cand in [{Fraction(1): Fraction(1)},
                 {Fraction(4): Fraction(9)},
                 {Fraction(0): Fraction(1, 1000)},
                 {Fraction(0): Fraction(1)}]:
        print(cand, "->", refute_supremum(cand, c, d))
